// @generated by:gauntlet run:godseye-e08-independent-gauntlet

import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AgentsFixture, agentsFixture } from "./helpers/agents-fixture.js";
import { required } from "./helpers/e08-values.js";

describe("E08 actual Foundation scoped budget admission", () => {
  let f: AgentsFixture;
  beforeEach(async () => {
    f = await agentsFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const budget = (change = {}) =>
    f.infrastructure.usage.putBudget(
      f.freshOwner(),
      {
        projectId: f.project.id,
        scope: "project",
        scopeId: f.project.id,
        expectedRevision: 0,
        limitMicros: 30000,
        windowSeconds: 60,
        maxRuns: 10,
        maxConcurrent: 1,
        ...change,
      },
      randomUUID(),
    );
  const read = async () =>
    required((await f.infrastructure.usage.overview(f.freshOwner())).budgets[0]);

  it("T-AC-805 admits only one simultaneous run against shared project concurrency", async () => {
    await budget();
    const a = await f.create(),
      b = await f.create({ role: "security" });
    const results = await Promise.allSettled([
      f.launch(a.id, a.revision),
      f.launch(b.id, b.revision),
    ]);
    expect(results.filter((result) => result.status === "fulfilled")).toHaveLength(1);
    expect(await read()).toMatchObject({ activeRuns: 1, reservedMicros: 10000, windowRuns: 1 });
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-805 binds profile and project limits together before provider dispatch", async () => {
    const profile = await f.create();
    await budget({ maxConcurrent: 5 });
    await budget({ scope: "profile", scopeId: profile.id, limitMicros: 9999 });
    await expect(f.launch(profile.id, profile.revision)).rejects.toMatchObject({
      code: "USAGE_BUDGET_EXCEEDED",
    });
    expect(
      (await f.infrastructure.usage.overview(f.freshOwner())).budgets.every(
        (row) => row.reservedMicros === 0,
      ),
    ).toBe(true);
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-806 frees concurrency after physical success even when token usage is absent", async () => {
    await budget();
    const profile = await f.create();
    f.provider.inspectScript = async (request) => ({
      state: "succeeded",
      stopped: true,
      providerRunId: request.providerRunId,
      output: "Physically stopped, usage absent",
    });
    const first = await f.launch(profile.id, profile.revision);
    await f.work();
    expect((await f.detail(first.id)).task.state).toBe("succeeded");
    expect(await read()).toMatchObject({ activeRuns: 0, reservedMicros: 0, spentMicros: 10000 });
    const next = await f.launch(profile.id, profile.revision, "A second admitted task");
    expect(next.state).toBe("queued");
    const summary = (await f.infrastructure.usage.overview(f.freshOwner())).summary;
    expect(summary.estimatedMicros).toBeNull();
    expect(summary.conservativeChargedMicros).toBe(10000);
  });

  it("T-AC-806 retains monetary and concurrent exposure when physical stop is unknown", async () => {
    await budget();
    const profile = await f.create();
    f.provider.submitScript = async () => ({
      state: "unknown",
      stopped: false,
      providerRunId: null,
    });
    const task = await f.launch(profile.id, profile.revision);
    await f.work();
    expect((await f.detail(task.id)).task.state).toBe("unknown");
    expect(await read()).toMatchObject({ activeRuns: 1, reservedMicros: 10000 });
    await f.infrastructure.usage.putBudget(
      f.freshOwner(),
      {
        projectId: f.project.id,
        scope: "project",
        scopeId: f.project.id,
        expectedRevision: 1,
        limitMicros: 0,
        windowSeconds: 60,
        maxRuns: 10,
        maxConcurrent: 1,
      },
      randomUUID(),
    );
    expect(await read()).toMatchObject({
      pressure: "overcommitted",
      activeRuns: 1,
      reservedMicros: 10000,
    });
    const other = await f.create({ role: "security" });
    await expect(f.launch(other.id, other.revision)).rejects.toThrow();
    expect(f.provider.submissions).toHaveLength(1);
  });

  it("T-AC-805 expires the finite run window while retaining the conservative charge history", async () => {
    await budget({ maxRuns: 1 });
    const profile = await f.create();
    await f.launch(profile.id, profile.revision);
    await f.work();
    await expect(
      f.launch(profile.id, profile.revision, "Still in rate window"),
    ).rejects.toMatchObject({ code: "USAGE_BUDGET_EXCEEDED" });
    f.clock.advance(60001);
    expect((await f.launch(profile.id, profile.revision, "New rate window")).state).toBe("queued");
    expect(
      (await f.infrastructure.usage.overview(f.freshOwner())).summary.conservativeChargedMicros,
    ).toBe(10000);
  });

  it("T-AC-805 requires fresh owner authority for policy expansion but permits conservative reduction", async () => {
    await budget();
    const aged = {
      ...f.freshOwner(),
      authenticatedAt: new Date(f.clock.now().getTime() - 300001).toISOString(),
    };
    const input = {
      projectId: f.project.id,
      scope: "project" as const,
      scopeId: f.project.id,
      expectedRevision: 1,
      limitMicros: 40000,
      windowSeconds: 60,
      maxRuns: 10,
      maxConcurrent: 1,
    };
    await expect(f.infrastructure.usage.putBudget(aged, input, randomUUID())).rejects.toMatchObject(
      { code: "STEP_UP_REQUIRED" },
    );
    expect(
      await f.infrastructure.usage.putBudget(aged, { ...input, limitMicros: 20000 }, randomUUID()),
    ).toMatchObject({ revision: 2, limitMicros: 20000 });
  });

  it("T-AC-806 allows queued cancellation and read-only recovery after an overcommitted reduction", async () => {
    await budget();
    const profile = await f.create(),
      task = await f.launch(profile.id, profile.revision);
    await budget({ expectedRevision: 1, limitMicros: 0 });
    expect((await f.detail(task.id)).task.state).toBe("queued");
    const cancelled = await f.infrastructure.agents.cancel(f.freshOwner(), task.id, randomUUID());
    expect(cancelled.state).toBe("cancelled");
    expect(await read()).toMatchObject({ activeRuns: 0, reservedMicros: 0 });
    expect(f.provider.submissions).toHaveLength(0);
  });
});
